// Build a single batch MERGE SQL from ALL rows in the API response
const response = $input.first().json;
const rows = response.data || [];
const pulledAt = new Date().toISOString();

function getAction(actions, type) {
  const a = (actions || []).find(x => x.action_type === type);
  return a ? Number(a.value) : 0;
}

function esc(s) {
  return String(s || '').replace(/'/g, "''");
}

const selects = rows.map(r => {
  const leads =
    getAction(r.actions, 'lead') +
    getAction(r.actions, 'onsite_conversion.lead_grouped') +
    getAction(r.actions, 'offsite_conversion.fb_pixel_lead');

  return `SELECT
    TRY_TO_TIMESTAMP_NTZ('${pulledAt}') AS PULLED_AT,
    TO_DATE('${r.date_start}') AS DATE_START,
    TO_DATE('${r.date_stop}') AS DATE_STOP,
    '${esc(r.account_id)}' AS AD_ACCOUNT_ID,
    '${esc(r.account_currency)}' AS CURRENCY,
    'ad' AS LEVEL,
    '${esc(r.campaign_id)}' AS CAMPAIGN_ID,
    '${esc(r.campaign_name)}' AS CAMPAIGN_NAME,
    '${esc(r.adset_id)}' AS ADSET_ID,
    '${esc(r.adset_name)}' AS ADSET_NAME,
    '${esc(r.ad_id)}' AS AD_ID,
    '${esc(r.ad_name)}' AS AD_NAME,
    ${Number(r.impressions || 0)} AS IMPRESSIONS,
    ${Number(r.clicks || 0)} AS CLICKS,
    ${Number(r.spend || 0)} AS SPEND,
    ${leads} AS LEADS,
    0 AS PURCHASES`;
}).join('\n  UNION ALL\n');

const sql = `MERGE INTO REVRYZE.RAW.META_ADS_DAILY t
USING (
  ${selects}
) s
ON  t.DATE_START     = s.DATE_START
AND t.AD_ACCOUNT_ID  = s.AD_ACCOUNT_ID
AND t.AD_ID          = s.AD_ID

WHEN MATCHED THEN UPDATE SET
  PULLED_AT     = s.PULLED_AT,
  DATE_STOP     = s.DATE_STOP,
  CURRENCY      = s.CURRENCY,
  LEVEL         = s.LEVEL,
  CAMPAIGN_ID   = s.CAMPAIGN_ID,
  CAMPAIGN_NAME = s.CAMPAIGN_NAME,
  ADSET_ID      = s.ADSET_ID,
  ADSET_NAME    = s.ADSET_NAME,
  AD_NAME       = s.AD_NAME,
  IMPRESSIONS   = s.IMPRESSIONS,
  CLICKS        = s.CLICKS,
  SPEND         = s.SPEND,
  LEADS         = s.LEADS,
  PURCHASES     = s.PURCHASES

WHEN NOT MATCHED THEN INSERT (
  PULLED_AT, DATE_START, DATE_STOP, AD_ACCOUNT_ID, CURRENCY, LEVEL,
  CAMPAIGN_ID, CAMPAIGN_NAME, ADSET_ID, ADSET_NAME, AD_ID, AD_NAME,
  IMPRESSIONS, CLICKS, SPEND, LEADS, PURCHASES
)
VALUES (
  s.PULLED_AT, s.DATE_START, s.DATE_STOP, s.AD_ACCOUNT_ID, s.CURRENCY, s.LEVEL,
  s.CAMPAIGN_ID, s.CAMPAIGN_NAME, s.ADSET_ID, s.ADSET_NAME, s.AD_ID, s.AD_NAME,
  s.IMPRESSIONS, s.CLICKS, s.SPEND, s.LEADS, s.PURCHASES
);`;

const nextUrl = response?.paging?.next || '';

return [{ json: { sql, row_count: rows.length, next_url: nextUrl } }];
